/*
 * atoms.cpp — Atom table implementation.
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "../include/atoms.h"

#include <cassert>
#include <cstring>
#include <cstdint>

static uint32_t fnv1a_32(const char *s)
{
    uint32_t hash = 2166136261U;
    uint32_t i;
    assert(s != nullptr);
    for (i = 0U; i < ATOM_MAX_LEN + 1U && s[i] != '\0'; ++i) {
        hash ^= static_cast<uint32_t>(static_cast<unsigned char>(s[i]));
        hash *= 16777619U;
    }
    return hash;
}

static uint32_t probe_slot(const AtomTable *t, const char *spelling,
                            uint32_t hash, int *found)
{
    uint32_t idx  = hash % ATOM_TABLE_CAPACITY;
    uint32_t step = 0U;

    assert(t != nullptr && spelling != nullptr && found != nullptr);
    *found = 0;

    for (step = 0U; step < ATOM_TABLE_CAPACITY; ++step) {
        const Atom *slot = &t->slots[idx];
        if (slot->id == ATOM_ID_INVALID) { return idx; }
        if (slot->hash == hash &&
            strncmp(slot->spelling, spelling, ATOM_MAX_LEN) == 0) {
            *found = 1;
            return idx;
        }
        idx = (idx + 1U) % ATOM_TABLE_CAPACITY;
    }
    return ATOM_TABLE_CAPACITY;
}

int atom_table_init(AtomTable *t)
{
    if (t == nullptr) { return -1; }
    memset(t, 0, sizeof(AtomTable));
    return 0;
}

AtomId atom_intern(AtomTable *t, const char *spelling)
{
    if (t == nullptr || spelling == nullptr) { return ATOM_ID_INVALID; }

    const size_t len = strnlen(spelling, ATOM_MAX_LEN + 1U);
    if (len > ATOM_MAX_LEN) { return ATOM_ID_INVALID; }

    const uint32_t hash = fnv1a_32(spelling);
    int found;
    const uint32_t idx = probe_slot(t, spelling, hash, &found);

    if (idx == ATOM_TABLE_CAPACITY) { return ATOM_ID_INVALID; }
    if (found) { return t->slots[idx].id; }

    assert(t->count < ATOM_TABLE_CAPACITY);
    Atom *slot = &t->slots[idx];
    memcpy(slot->spelling, spelling, len);
    slot->spelling[len] = '\0';
    slot->hash = hash;
    slot->id   = static_cast<AtomId>(t->count + ATOM_ID_MIN);
    t->count++;
    return slot->id;
}

AtomId atom_lookup(const AtomTable *t, const char *spelling)
{
    if (t == nullptr || spelling == nullptr) { return ATOM_ID_INVALID; }

    const size_t len = strnlen(spelling, ATOM_MAX_LEN + 1U);
    if (len > ATOM_MAX_LEN) { return ATOM_ID_INVALID; }

    const uint32_t hash = fnv1a_32(spelling);
    int found;
    const uint32_t idx = probe_slot(t, spelling, hash, &found);

    if (!found || idx == ATOM_TABLE_CAPACITY) { return ATOM_ID_INVALID; }
    return t->slots[idx].id;
}

const char *atom_spelling(const AtomTable *t, AtomId id)
{
    if (t == nullptr || id == ATOM_ID_INVALID) { return nullptr; }
    for (uint32_t i = 0U; i < ATOM_TABLE_CAPACITY; ++i) {
        if (t->slots[i].id == id) { return t->slots[i].spelling; }
    }
    return nullptr;
}

uint32_t atom_count(const AtomTable *t)
{
    if (t == nullptr) { return 0U; }
    return t->count;
}

/*
 * variables.cpp — Logic variable registry implementation.
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "../include/variables.h"

#include <cassert>
#include <cstring>

static VarEntry *entry_at(VarRegistry *r, VarId id)
{
    assert(r != nullptr);
    if (id == VAR_ID_INVALID || id < VAR_ID_MIN) { return nullptr; }
    const uint32_t idx = id - VAR_ID_MIN;
    if (idx >= VAR_REGISTRY_CAPACITY || idx >= r->count) { return nullptr; }
    return &r->entries[idx];
}

static const VarEntry *entry_at_c(const VarRegistry *r, VarId id)
{
    assert(r != nullptr);
    if (id == VAR_ID_INVALID || id < VAR_ID_MIN) { return nullptr; }
    const uint32_t idx = id - VAR_ID_MIN;
    if (idx >= VAR_REGISTRY_CAPACITY || idx >= r->count) { return nullptr; }
    return &r->entries[idx];
}

int var_registry_init(VarRegistry *r)
{
    if (r == nullptr) { return -1; }
    memset(r, 0, sizeof(VarRegistry));
    return 0;
}

VarId var_alloc(VarRegistry *r, const char *name)
{
    if (r == nullptr || name == nullptr) { return VAR_ID_INVALID; }
    if (r->count >= VAR_REGISTRY_CAPACITY) { return VAR_ID_INVALID; }

    const size_t len = strnlen(name, VAR_NAME_MAX_LEN + 1U);
    if (len > VAR_NAME_MAX_LEN) { return VAR_ID_INVALID; }

    const VarId new_id = static_cast<VarId>(r->count + VAR_ID_MIN);
    VarEntry *slot = &r->entries[r->count];
    memset(slot, 0, sizeof(VarEntry));
    memcpy(slot->name, name, len);
    slot->name[len] = '\0';
    slot->tag = TERM_UNBOUND;
    slot->id  = new_id;
    r->count++;
    return new_id;
}

int var_bind_atom(VarRegistry *r, VarId id, AtomId atom_id)
{
    if (r == nullptr || atom_id == ATOM_ID_INVALID) { return -1; }
    VarEntry *e = entry_at(r, id);
    if (e == nullptr || e->tag != TERM_UNBOUND) { return -1; }
    e->tag          = TERM_ATOM;
    e->value.atom_id = atom_id;
    return 0;
}

int var_bind_var(VarRegistry *r, VarId id, VarId other_id)
{
    if (r == nullptr) { return -1; }
    if (id == other_id) { return 0; }
    VarEntry *e = entry_at(r, id);
    if (e == nullptr) { return -1; }
    if (entry_at(r, other_id) == nullptr) { return -1; }
    if (e->tag != TERM_UNBOUND) { return -1; }
    e->tag          = TERM_VAR;
    e->value.var_id = other_id;
    return 0;
}

int var_bind_term(VarRegistry *r, VarId id, TermRef ref)
{
    if (r == nullptr || ref == 0U) { return -1; }
    VarEntry *e = entry_at(r, id);
    if (e == nullptr || e->tag != TERM_UNBOUND) { return -1; }
    e->tag            = TERM_TERMREF;
    e->value.term_ref = ref;
    return 0;
}

WalkResult var_walk(const VarRegistry *r, VarId id)
{
    WalkResult result;
    result.tag          = TERM_UNBOUND;
    result.value.var_id = VAR_ID_INVALID;
    result.root_id      = VAR_ID_INVALID;

    if (r == nullptr || id == VAR_ID_INVALID) { return result; }

    VarId current = id;
    for (uint32_t steps = 0U; steps < VAR_REGISTRY_CAPACITY; ++steps) {
        const VarEntry *e = entry_at_c(r, current);
        if (e == nullptr) { return result; }
        if (e->tag != TERM_VAR) {
            result.tag      = e->tag;
            result.value    = e->value;
            result.root_id  = current;
            return result;
        }
        current = e->value.var_id;
    }
    assert(false);
    return result;
}

int var_reset(VarRegistry *r)
{
    if (r == nullptr) { return -1; }
    memset(r, 0, sizeof(VarRegistry));
    return 0;
}

uint32_t var_count(const VarRegistry *r)
{
    if (r == nullptr) { return 0U; }
    return r->count;
}

/*
 * terms.cpp — Term arena implementation.
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "../include/terms.h"
#include <cassert>
#include <cstring>

int term_arena_init(TermArena *a)
{
    if (a == nullptr) { return -1; }
    memset(a, 0, sizeof(TermArena));
    return 0;
}

TermRef term_make_atom(TermArena *a, AtomId id)
{
    if (a == nullptr || id == ATOM_ID_INVALID) { return TERM_REF_INVALID; }
    if (a->count >= TERM_ARENA_CAPACITY) { return TERM_REF_INVALID; }

    const TermRef ref = static_cast<TermRef>(a->count + 1U);
    Term *t = &a->nodes[a->count];
    memset(t, 0, sizeof(Term));
    t->kind         = TERM_KIND_ATOM;
    t->data.atom_id = id;
    t->ref          = ref;
    a->count++;
    return ref;
}

TermRef term_make_var(TermArena *a, VarId id, const char *name)
{
    if (a == nullptr || id == VAR_ID_INVALID) { return TERM_REF_INVALID; }
    if (a->count >= TERM_ARENA_CAPACITY) { return TERM_REF_INVALID; }

    const TermRef ref = static_cast<TermRef>(a->count + 1U);
    Term *t = &a->nodes[a->count];
    memset(t, 0, sizeof(Term));
    t->kind            = TERM_KIND_VAR;
    t->data.var.var_id = id;
    if (name != nullptr) {
        const size_t nlen = strnlen(name, VAR_NAME_MAX_LEN);
        memcpy(t->data.var.name, name, nlen);
        t->data.var.name[nlen] = '\0';
    } else {
        t->data.var.name[0] = '_';
        t->data.var.name[1] = '\0';
    }
    t->ref = ref;
    a->count++;
    return ref;
}

TermRef term_make_int(TermArena *a, int32_t val)
{
    if (a == nullptr) { return TERM_REF_INVALID; }
    if (a->count >= TERM_ARENA_CAPACITY) { return TERM_REF_INVALID; }

    const TermRef ref = static_cast<TermRef>(a->count + 1U);
    Term *t = &a->nodes[a->count];
    memset(t, 0, sizeof(Term));
    t->kind         = TERM_KIND_INT;
    t->data.int_val = val;
    t->ref          = ref;
    a->count++;
    return ref;
}

TermRef term_make_compound(TermArena *a, AtomId functor, uint8_t arity,
                            const TermRef *args)
{
    if (a == nullptr || functor == ATOM_ID_INVALID) { return TERM_REF_INVALID; }
    if (arity > TERM_MAX_ARITY) { return TERM_REF_INVALID; }
    if (arity > 0U && args == nullptr) { return TERM_REF_INVALID; }
    if (a->count >= TERM_ARENA_CAPACITY) { return TERM_REF_INVALID; }
    if (a->args.count + static_cast<uint32_t>(arity) > ARG_POOL_CAPACITY) {
        return TERM_REF_INVALID;
    }

    const TermRef ref = static_cast<TermRef>(a->count + 1U);
    Term *t = &a->nodes[a->count];
    memset(t, 0, sizeof(Term));
    t->kind                    = TERM_KIND_COMPOUND;
    t->data.compound.functor   = functor;
    t->data.compound.arity     = arity;
    t->data.compound.arg_start = a->args.count;
    t->ref                     = ref;

    for (uint8_t i = 0U; i < arity; ++i) {
        assert(a->args.count < ARG_POOL_CAPACITY);
        a->args.slots[a->args.count] = args[i];
        a->args.count++;
    }

    a->count++;
    return ref;
}

const Term *term_get(const TermArena *a, TermRef ref)
{
    if (a == nullptr || ref == TERM_REF_INVALID) { return nullptr; }
    const uint32_t idx = ref - 1U;
    if (idx >= a->count) { return nullptr; }
    return &a->nodes[idx];
}

TermRef term_arg(const TermArena *a, TermRef ref, uint8_t n)
{
    const Term *t = term_get(a, ref);
    if (t == nullptr || t->kind != TERM_KIND_COMPOUND) { return TERM_REF_INVALID; }
    if (n >= t->data.compound.arity) { return TERM_REF_INVALID; }
    const uint32_t pool_idx = t->data.compound.arg_start + static_cast<uint32_t>(n);
    assert(pool_idx < ARG_POOL_CAPACITY);
    return a->args.slots[pool_idx];
}

TermKind term_kind(const TermArena *a, TermRef ref)
{
    const Term *t = term_get(a, ref);
    if (t == nullptr) { return static_cast<TermKind>(0); }
    return t->kind;
}

/*
 * atoms.hpp — Atom table for the Epilog inference engine.
 *
 * An atom is an immutable, interned string. Every unique spelling maps to
 * exactly one AtomId. Comparisons are therefore O(1) integer comparisons.
