    char     spelling[ATOM_MAX_LEN + 1U];
    uint32_t hash;
    AtomId   id;
};

struct AtomTable {
    Atom     slots[ATOM_TABLE_CAPACITY];
    uint32_t count = 0U;
};

/* atom_table_init — zero-initialise *t. Returns 0 or -1. */
int atom_table_init(AtomTable *t);

